export function checkInteractionPair(drug1: string, drug2: string): DrugInteractionRule[] {
  const d1 = drug1.toLowerCase();
  const d2 = drug2.toLowerCase();
  return MASTER_DRUG_INTERACTIONS_REGISTRY.filter(r => 
    (r.primaryDrug.toLowerCase().includes(d1) && r.interactingDrug.toLowerCase().includes(d2)) ||
    (r.primaryDrug.toLowerCase().includes(d2) && r.interactingDrug.toLowerCase().includes(d1))
  );
}
